"""Exercise a big-endian resource archive without including game data."""

import struct

import pytest

from decompassets import formats
from decompassets.n64 import be_iwad_images, lzhuf

# Generated by the reference encoder from a tiny synthetic picture and red palette.
PICTURE = bytes.fromhex('0000002041428000040710cc1f60a027a87770d880')
PALETTE = bytes.fromhex('00000300c041028003f806f006f0077003f80400')


def archive():
    data = bytearray(b'IWAD' + b'\0' * 8)
    entries = []
    for name, content in [('S_START', b''), ('PIC', PICTURE), ('S_END', b''), ('PLAYPAL', PALETTE),
                          ('MARK1', b''), ('MARK2', b''), ('MARK3', b''), ('MARK4', b'')]:
        offset = len(data) if content else 0
        data.extend(content)
        entries.append((offset, len(content), name.encode().ljust(8, b'\0')))
    directory = len(data)
    for row in entries:
        data.extend(struct.pack('>II8s', *row))
    struct.pack_into('>II', data, 4, len(entries), directory)
    return bytes(data)


def test_lsb_stream_decodes_and_rejects_truncation():
    raw = lzhuf.unpack(PICTURE[4:], 32, lsb_variant=True)
    assert raw[:4] == b'\x00\x04\x00\x04'
    assert raw[16:] == bytes([0, 1, 2, 3] * 4)
    with pytest.raises(formats.AssetError):
        lzhuf.unpack(PICTURE[4:8], 32, lsb_variant=True)


def test_archive_preview_and_bad_directory():
    data = archive()
    regions = be_iwad_images.regions(data)
    assert len(regions) == 1
    assert (regions[0]['width'], regions[0]['height']) == (4, 4)
    assert be_iwad_images.preview(data, regions[0], {})['mime'] == 'image/png'
    corrupt = bytearray(data)
    struct.pack_into('>I', corrupt, 8, len(data))
    assert be_iwad_images.regions(corrupt) == []
